    """Store or return the shared intent/plan for this session."""
    import json, os
    p = "intent.json"
    if text:
        with open(p, "w") as f:
            json.dump({"intent": text}, f)
        return "intent stored"
    try:
        with open(p) as f:
            return f.read()
    except FileNotFoundError:
        return "no intent yet"

