def world_search(query, top_k=5):
    """Call world MCP api_search; return parsed JSON."""
    import json, requests
    url = "http://127.0.0.1:41299/mcp/9385f0dfecae14a3cc2ed2869959a99f"
    r = requests.post(url, json={"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"api_search","arguments":{"query":query,"top_k":top_k}}},
                      headers={"Content-Type":"application/json","Accept":"application/json, text/event-stream"}, timeout=30)
    data = r.json()
    for c in data.get("result",{}).get("content",[]):
        if c.get("type")=="text": return c["text"]
    return json.dumps(data)

def world_fetch(method, url, params=None, body=None):
    """Call world MCP api_fetch. params/body accept JSON strings or dicts."""
    import json, requests
    mcp = "http://127.0.0.1:41299/mcp/9385f0dfecae14a3cc2ed2869959a99f"
    args = {"method": method, "url": url, "params": None, "body": None}
    if params is not None:
        args["params"] = params if isinstance(params, str) else json.dumps(params)
    if body is not None:
        args["body"] = body if isinstance(body, str) else json.dumps(body)
    r = requests.post(mcp, json={"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"api_fetch","arguments":args}},
                      headers={"Content-Type":"application/json","Accept":"application/json, text/event-stream"}, timeout=60)
    data = r.json()
    if "error" in data:
        return "MCP ERROR: " + json.dumps(data["error"])
    out = []
    for c in data.get("result",{}).get("content",[]):
        if c.get("type")=="text": out.append(c["text"])
        else: out.append(json.dumps(c))
    if data.get("result",{}).get("isError"):
        return "TOOL ERROR:\n" + "\n".join(out)
    return "\n".join(out)

